
-- ======================================================
-- MIGRACIÓN DE DATOS INTEGRAL (PAPEL -> DIGITAL)
-- OLYMPUS ERP v3.5 - DATA COMPLETA RESTAURADA
-- ======================================================

-- 1. SUCURSALES (13)
ON CONFLICT (id) DO UPDATE SET nombre = EXCLUDED.nombre;

-- 2. CLIENTES (50)
ON CONFLICT (id) DO UPDATE SET balance = EXCLUDED.balance;

-- 3. PROVEEDORES (50)
ON CONFLICT (id) DO UPDATE SET nombre = EXCLUDED.nombre;

-- 4. PRODUCTOS (50)
ON CONFLICT (id) DO UPDATE SET stock = EXCLUDED.stock;

-- 5. FACTURAS (50)
ON CONFLICT (id) DO UPDATE SET total = EXCLUDED.total;

-- 6. ITEMS DE FACTURA (50)
ON CONFLICT (id) DO UPDATE SET subtotal = EXCLUDED.subtotal;

-- 7. CUENTAS POR COBRAR (50)
ON CONFLICT (id) DO UPDATE SET monto_pendiente = EXCLUDED.monto_pendiente;

-- 8. GASTOS (50)
ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto;

-- 9. MOVIMIENTOS DE INVENTARIO (50)
ON CONFLICT (id) DO UPDATE SET cantidad = EXCLUDED.cantidad;